css:
.game-button {
  background-color: #ff7979;
  color: #fff;
  border: none;
  border-radius: 20px;
  padding: 10px 20px;
  font-size: 18px;
  text-transform: uppercase;
  letter-spacing: 2px;
  font-weight: bold;
  box-shadow: 2px 2px 10px #ff7979;
  transition: all 0.2s ease-in-out;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.play-icon {
  width: 24px;
  height: 24px;
  fill: #fff;
  margin-right: 10px;
}

.game-button:hover {
  background-color: #2f3640;
  color: #ff7979;
  box-shadow: 2px 2px 20px #2f3640;
  transform: translateY(-2px);
}
